import itertools
from collections import deque

def solve_small_n(n, l_shape):
    # l_shape is a list of 3 relative offsets: [(0,0), (1,0), (0,1)]
    start_state = tuple([0] * (n * n))
    queue = deque([(start_state, 0)])
    visited = {start_state}

    while queue:
        state, dist = queue.popleft()
        if dist > 0 and state == start_state:
            return True

        # Move 1: Place L-tromino
        for r in range(n):
            for c in range(n):
                # Check if L-tromino fits and cells are empty
                possible = True
                cells = []
                for dr, dc in l_shape:
                    nr, nc = r + dr, c + dc
                    if not (0 <= nr < n and 0 <= nc < n) or state[nr * n + nc] == 1:
                        possible = False
                        break
                    cells.append(nr * n + nc)

                if possible:
                    new_state = list(state)
                    for cell in cells:
                        new_state[cell] = 1
                    new_state = tuple(new_state)
                    if new_state not in visited:
                        visited.add(new_state)
                        queue.append((new_state, dist + 1))

        # Move 2: Remove column
        for c in range(n):
            if all(state[r * n + c] == 1 for r in range(n)):
                new_state = list(state)
                for r in range(n):
                    new_state[r * n + c] = 0
                new_state = tuple(new_state)
                if new_state not in visited:
                    visited.add(new_state)
                    queue.append((new_state, dist + 1))

        # Move 3: Remove row
        for r in range(n):
            if all(state[r * n + c] == 1 for c in range(n)):
                new_state = list(state)
                for c in range(n):
                    new_state[r * n + c] = 0
                new_state = tuple(new_state)
                if new_state not in visited:
                    visited.add(new_state)
                    queue.append((new_state, dist + 1))
    return False

